        &&& self.rid@ == replica.spec_id()
        &&& self.fc_client@.instance_id() == replica.flat_combiner_instance@.id()
        &&& self.batch_perm@@.pcell == replica.contexts[self.thread_id_spec() as int].batch.0.id()
    }

